import {confirmButtonResult} from './button-feedback.js';
import {OUTFIT_SLOTS,minerOutfit,minerOutfitKey} from './miner-outfit.js';
import {nextLevelXP} from './pillars.js';
import {petsServiceView} from './pets-service.js';
import {serviceShadow} from './approved-service-host.js';
const markup="<div id=\"gv-wardrobe-service\"><div class=\"scene\"> <section class=\"window\" id=\"gvw-window\" aria-labelledby=\"gvw-title\">\n  <header class=\"head\"><svg class=\"portrait\" viewBox=\"84 41 156 160\" aria-hidden=\"true\"><image id=\"gvw-portrait\" width=\"320\" height=\"320\"/></svg><h2 id=\"gvw-title\">Minerador</h2><span class=\"level\" id=\"gvw-level\"></span><button class=\"button close\" id=\"gvw-close\" aria-label=\"Fechar Vestiário\">×</button></header>\n  <nav class=\"sections\" aria-label=\"Seções do personagem\"><button class=\"button current\" id=\"gvw-clothes\" aria-current=\"page\">Vestiário</button><button class=\"button pets\" id=\"gvw-pets\">Pets <span class=\"count\" id=\"gvw-pet-count\"></span><span aria-hidden=\"true\">↗</span></button></nav>\n  <div class=\"content\">\n   <section class=\"character\" aria-label=\"Prévia do personagem\"><div class=\"stage\"><div class=\"floor-shadow\" aria-hidden=\"true\"></div><img class=\"miner\" id=\"gvw-miner\" alt=\"Minerador com as roupas em uso\"><button class=\"button pose\" id=\"gvw-pose\" aria-label=\"Trocar pose: confiante\" aria-pressed=\"true\"><span aria-hidden=\"true\">↻</span> Pose</button></div><div class=\"xp\"><div class=\"xp-line\"><span>XP</span><span id=\"gvw-xp-value\"></span></div><div class=\"track\" id=\"gvw-xp\" role=\"progressbar\" aria-label=\"Experiência para o próximo nível\"><span></span></div></div></section>\n   <section class=\"catalog\" aria-label=\"Coleção de roupas\"><nav class=\"categories\" id=\"gvw-categories\" role=\"tablist\" aria-label=\"Categorias de roupa\"></nav><div class=\"catalog-title\"><h3 id=\"gvw-category-name\"></h3><span id=\"gvw-piece-count\"></span></div><div class=\"pieces\" id=\"gvw-pieces\" role=\"tabpanel\"></div><nav class=\"pager\" id=\"gvw-pages\" aria-label=\"Páginas de roupas\"><button class=\"button\" id=\"gvw-prev\" aria-label=\"Página anterior de roupas\">‹</button><span id=\"gvw-page\"></span><button class=\"button\" id=\"gvw-next\" aria-label=\"Próxima página de roupas\">›</button></nav></section>\n  </div>\n  <div class=\"message\" id=\"gvw-message\" role=\"alert\"></div><div class=\"sr\" id=\"gvw-live\" aria-live=\"polite\"></div>\n  <footer class=\"footer\"><button class=\"button\" id=\"gvw-talents\"><img id=\"gvw-tree-icon\" alt=\"\">Talentos <span class=\"points\"><img id=\"gvw-point-icon\" alt=\"Pontos de talento\"><b id=\"gvw-points\"></b></span></button><button class=\"button\" id=\"gvw-equipment\" aria-label=\"Ver equipamentos na Forja\"><img id=\"gvw-forge-icon\" alt=\"\">Forja <span aria-hidden=\"true\">↗</span></button></footer>\n </section></div></div>";
const crops={hat:'74 45 172 88',shirt:'98 186 124 59',pants:'108 244 104 24',shoes:'108 262 104 34',glasses:'102 135 116 42'};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountApprovedWardrobe(dialog,profile,{initialUi={},onUiState=()=>{},onEquip,onPets,onNavigate,onClose,onCommand=()=>{},softMode=()=>false}={}){
 const shadow=serviceShadow(dialog,markup),style=dialog.ownerDocument.createElement('link');style.rel='stylesheet';style.href='approved-wardrobe-ui.css';shadow.prepend(style);
 const root=shadow.querySelector('#gv-wardrobe-service'),$=id=>root.querySelector('#'+id),categories=['all',...Object.keys(OUTFIT_SLOTS)],motion=matchMedia('(prefers-reduced-motion: reduce)');
 let category=categories.includes(initialUi.category)?initialUi.category:'all',page=Number.isSafeInteger(initialUi.page)&&initialUi.page>=0?initialUi.page:0,pose=['front','wardrobe'].includes(initialUi.pose)?initialUi.pose:'wardrobe',capacity=4,disposed=false,animations=[];
 const reduced=()=>softMode()||motion.matches,remember=()=>onUiState({category,page,pose}),figure=(p=profile)=>'assets/miner-living-v7/'+minerOutfitKey(p)+'/',entries=()=>Object.entries(OUTFIT_SLOTS).flatMap(([slot,s])=>s.items.map(([id,name])=>({slot,id,name}))),filtered=()=>entries().filter(i=>category==='all'||i.slot===category);
 function crop(slot,p=profile){return '<svg viewBox="'+crops[slot]+'" aria-hidden="true"><image href="'+figure(p)+'front.png" width="320" height="320"/></svg>';}
 function updateAvatar(){const outfit=minerOutfit(profile);$('gvw-miner').src=figure()+pose+'.png';$('gvw-miner').alt='Minerador: '+OUTFIT_SLOTS.hat.items.find(i=>i[0]===outfit.hat)[1]+', blusa '+OUTFIT_SLOTS.shirt.items.find(i=>i[0]===outfit.shirt)[1].toLowerCase()+', pose '+(pose==='wardrobe'?'confiante':'em pé');$('gvw-portrait').setAttribute('href',figure()+'front.png');$('gvw-pose').setAttribute('aria-pressed',String(pose==='wardrobe'));$('gvw-pose').setAttribute('aria-label','Trocar pose: '+(pose==='wardrobe'?'confiante':'em pé'));}
 function renderCategories(){for(const key of categories){const button=$('gvw-tab-'+key);if(key!=='all')button.innerHTML=crop(key);button.setAttribute('aria-selected',String(category===key));}}
 function renderGrid(focusKey){const list=filtered(),pages=Math.max(1,Math.ceil(list.length/capacity)),outfit=minerOutfit(profile);page=Math.min(page,pages-1);$('gvw-category-name').textContent=category==='all'?'Roupas':OUTFIT_SLOTS[category].name;$('gvw-piece-count').textContent=list.length+(list.length===1?' peça':' peças');$('gvw-pieces').setAttribute('aria-labelledby','gvw-tab-'+category);$('gvw-pieces').innerHTML=list.slice(page*capacity,(page+1)*capacity).map(item=>{const selected=outfit[item.slot]===item.id,p={homeCollection:{outfit:{...outfit,[item.slot]:item.id}}};return '<button class="piece" data-slot="'+item.slot+'" data-item="'+item.id+'" data-outfit-slot="'+item.slot+'" data-outfit-item="'+item.id+'" aria-pressed="'+selected+'" aria-label="'+escape(OUTFIT_SLOTS[item.slot].name+': '+item.name+(selected?', em uso':', usar'))+'">'+crop(item.slot,p)+'<span>'+escape(item.name)+'</span>'+(selected?'<b class="equipped" aria-hidden="true">✓</b>':'')+'</button>';}).join('');$('gvw-pages').hidden=pages===1;$('gvw-page').textContent=(page+1)+'/'+pages;$('gvw-prev').disabled=page===0;$('gvw-next').disabled=page===pages-1;if(focusKey)root.querySelector('[data-slot="'+focusKey.slot+'"][data-item="'+focusKey.id+'"]')?.focus({preventScroll:true});}
 function render(){renderCategories();renderGrid();updateAvatar();const xp=profile.experience,next=nextLevelXP(xp.level),pets=petsServiceView(profile);$('gvw-level').textContent='Nv. '+xp.level;$('gvw-xp-value').textContent=xp.xp.toLocaleString('pt-BR')+'/'+next.toLocaleString('pt-BR');$('gvw-xp').setAttribute('aria-valuemin','0');$('gvw-xp').setAttribute('aria-valuemax',next);$('gvw-xp').setAttribute('aria-valuenow',xp.xp);$('gvw-xp').querySelector('span').style.width=xp.xp/next*100+'%';$('gvw-points').textContent=xp.points;$('gvw-talents').classList.toggle('has-points',xp.points>0);$('gvw-talents').setAttribute('aria-label','Ver talentos: '+xp.points+' pontos disponíveis');$('gvw-pet-count').textContent=pets.pets.filter(p=>p.owned).length+'/'+pets.pets.length;root.dataset.soft=String(reduced());}
 function pop(){animations.forEach(a=>a.cancel());animations=[];const soft=reduced();animations.push($('gvw-miner').animate(soft?[{opacity:.85},{opacity:1}]:[{transform:'translateX(-50%) scale(.96)'},{transform:'translateX(-50%) scale(1.035)',offset:.6},{transform:'translateX(-50%) scale(1)'}],{duration:soft?120:260,easing:'cubic-bezier(.2,.7,.2,1)'}));}
 $('gvw-categories').innerHTML=categories.map(key=>'<button class="button category" id="gvw-tab-'+key+'" role="tab" aria-controls="gvw-pieces" aria-label="'+(key==='all'?'Todas as roupas':OUTFIT_SLOTS[key].name)+'" data-category="'+key+'" '+(key!=='all'?'data-outfit-tab="'+key+'"':'')+'>'+(key==='all'?'Todas':'')+'</button>').join('');
 $('gvw-categories').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b||disposed)return;category=b.dataset.category;page=0;$('gvw-message').textContent='';renderCategories();renderGrid();remember();});
 $('gvw-categories').addEventListener('keydown',e=>{const b=e.target.closest('[data-category]');if(!b||disposed||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let i=categories.indexOf(b.dataset.category);i=e.key==='Home'?0:e.key==='End'?categories.length-1:(i+(e.key==='ArrowRight'?1:categories.length-1))%categories.length;category=categories[i];page=0;renderCategories();renderGrid();$('gvw-tab-'+category).focus();remember();});
 $('gvw-pieces').addEventListener('click',e=>{const b=e.target.closest('[data-slot]');if(!b||disposed)return;const slot=b.dataset.slot,id=b.dataset.item;if(minerOutfit(profile)[slot]===id)return;const result=onEquip?.(slot,id);if(!result?.ok){$('gvw-message').textContent=result?.message||'Não foi possível salvar. Visual anterior mantido.';$('gvw-live').textContent='';return;}confirmButtonResult(b,'set');$('gvw-message').textContent='';renderCategories();renderGrid({slot,id});updateAvatar();$('gvw-live').textContent=OUTFIT_SLOTS[slot].items.find(i=>i[0]===id)[1]+' em uso.';pop();remember();});
 $('gvw-prev').onclick=()=>{page--;renderGrid();if($('gvw-prev').disabled)$('gvw-next').focus();remember();};$('gvw-next').onclick=()=>{page++;renderGrid();if($('gvw-next').disabled)$('gvw-prev').focus();remember();};$('gvw-pose').onclick=()=>{pose=pose==='wardrobe'?'front':'wardrobe';updateAvatar();$('gvw-live').textContent='Pose '+(pose==='wardrobe'?'confiante':'em pé')+'.';remember();};
 $('gvw-close').onclick=onClose;$('gvw-pets').onclick=onPets;$('gvw-talents').onclick=()=>onNavigate?.('tree');$('gvw-equipment').onclick=()=>onNavigate?.('forge');$('gvw-clothes').onclick=()=>{category='all';page=0;renderCategories();renderGrid();remember();};
 root.addEventListener('keydown',e=>{if(e.key==='Escape'&&!disposed){e.preventDefault();e.stopPropagation();onClose?.();}});const command=e=>{const b=e.target.closest('button');if(b&&!b.disabled&&!disposed)onCommand();};root.addEventListener('click',command,true);
 const onMotion=()=>{animations.forEach(a=>a.cancel());root.dataset.soft=String(reduced());};motion.addEventListener('change',onMotion);
 for(const [id,url]of [['gvw-tree-icon','assets/tree-ecos-v3/tree-emblem.png'],['gvw-forge-icon','assets/forge-v6/anvil-v05-attempt-3-256.png'],['gvw-point-icon','assets/descent-choice/summary/star.png']])$(id).src=url;
 capacity=root.clientWidth>=1000?8:4;render();const resize=new ResizeObserver(()=>{if(disposed)return;const next=root.clientWidth>=1000?8:4;if(next!==capacity){const start=page*capacity;capacity=next;page=Math.floor(start/capacity);renderGrid();}});resize.observe(root);queueMicrotask(()=>{if(dialog.open&&!disposed)$('gvw-close').focus({preventScroll:true});});
 return ()=>{disposed=true;resize.disconnect();motion.removeEventListener('change',onMotion);root.removeEventListener('click',command,true);animations.forEach(a=>a.cancel());};
}
